def audit_purchases_cutoff_and_goods_in_transit(
    purchases_sample: list = None,
    fiscal_year_end: str = "2026-12-31"
) -> dict:
    # Substantive Purchase Cut-Off & Goods in Transit (Incoterms) Evaluator
    if purchases_sample is None:
        purchases_sample = [
            {"po": "PO-7701", "supplier": "Tokyo Precision Co.", "amount": 6500000.0, "ship_date": "2026-12-27", "arrival_date": "2027-01-05", "incoterm": "FOB_SHIPPING_POINT", "recorded_in_ap_ye": False, "in_transit_inv_ye": False}, # Omitted in-transit!
            {"po": "PO-7702", "supplier": "Munich Turbine Works", "amount": 4200000.0, "ship_date": "2026-12-28", "arrival_date": "2027-01-04", "incoterm": "FOB_DESTINATION", "recorded_in_ap_ye": True, "in_transit_inv_ye": True}, # Premature recording!
            {"po": "PO-7703", "supplier": "American Steel Corp.", "amount": 3100000.0, "ship_date": "2026-12-24", "arrival_date": "2026-12-29", "incoterm": "FOB_DESTINATION", "recorded_in_ap_ye": True, "in_transit_inv_ye": True} # Valid pre-YE arrival!
        ]

    cutoff_adjustments = []

    for p in purchases_sample:
        po = p['po']
        amt = p['amount']
        ship = p['ship_date']
        arr = p['arrival_date']
        term = p['incoterm']
        in_ap = p['recorded_in_ap_ye']

        # 1. FOB Shipping Point: Title transfers upon shipment
        if term == "FOB_SHIPPING_POINT":
            if ship <= fiscal_year_end and not in_ap:
                cutoff_adjustments.append({
                    'po': po,
                    'defect': "UNRECORDED_GOODS_IN_TRANSIT_FOB_SHIPPING_POINT",
                    'amount': amt,
                    'adjustment': f"Dr: Inventory (Goods in Transit) ${amt:,.2f} | Cr: Accounts Payable ${amt:,.2f}"
                })

        # 2. FOB Destination: Title transfers upon physical arrival
        elif term == "FOB_DESTINATION":
            if arr > fiscal_year_end and in_ap:
                cutoff_adjustments.append({
                    'po': po,
                    'defect': "PREMATURE_RECORDING_FOB_DESTINATION_ARRIVED_POST_YE",
                    'amount': amt,
                    'adjustment': f"Dr: Accounts Payable ${amt:,.2f} | Cr: Inventory ${amt:,.2f}"
                })

    return {
        'purchases_audited_count': len(purchases_sample),
        'cutoff_errors_count': len(cutoff_adjustments),
        'total_adjustment_volume': sum(a['amount'] for a in cutoff_adjustments),
        'cutoff_verdict': "PURCHASE_CUTOFF_CLEAN" if len(cutoff_adjustments) == 0 else "PURCHASE_CUTOFF_MISSTATEMENTS_ADJUSTMENTS_REQUIRED",
        'adjustments_schedule': cutoff_adjustments
    }

cutoff_eval = audit_purchases_cutoff_and_goods_in_transit()
print("=== Substantive Purchase Cut-Off & Goods in Transit Report ===")
print(f"Purchases Sampled:           {cutoff_eval['purchases_audited_count']}")
print(f"Cut-Off Exceptions Found:    {cutoff_eval['cutoff_errors_count']}")
print(f"Total Adjustment Dollar Vol: ${cutoff_eval['total_adjustment_volume']:,.2f}")
print(f"Cut-Off Assurance Verdict:   {cutoff_eval['cutoff_verdict']}")
print("\nMandated Cut-Off Adjustments:")
for adj in cutoff_eval['adjustments_schedule']:
    print(f" - [{adj['po']}] {adj['defect']} (${adj['amount']:,.2f}):\n     {adj['adjustment']}")
